PRAGMA foreign_keys=OFF;
BEGIN;
PRAGMA writable_schema = on;
CREATE TABLE IF NOT EXISTS  trailing_stop (
                symbol TEXT PRIMARY KEY,
                entry_price REAL,
                highest_price REAL,
                sl_price REAL,
                activated INTEGER DEFAULT 0,
                updated_at REAL
            );
CREATE TABLE IF NOT EXISTS  portfolio (
                symbol TEXT PRIMARY KEY,
                quantity REAL,
                entry_price REAL,
                strategy TEXT,
                opened_at REAL,
                updated_at REAL,
                stop_loss REAL,
                take_profit REAL,
                invest_pct REAL DEFAULT 0
            );
CREATE TABLE IF NOT EXISTS  drawdown (
                id INTEGER PRIMARY KEY CHECK (id = 1),
                high_watermark REAL DEFAULT 0,
                current_drawdown_pct REAL DEFAULT 0,
                max_drawdown_pct REAL DEFAULT 0,
                tripped_count INTEGER DEFAULT 0,
                tripped_at REAL,
                reset_at REAL,
                history TEXT,
                updated_at REAL
            );
CREATE TABLE IF NOT EXISTS  risk_guard (
                id INTEGER PRIMARY KEY CHECK (id = 1),
                daily_pnl REAL DEFAULT 0,
                streak INTEGER DEFAULT 0,
                last_reset REAL,
                updated_at REAL
            );
CREATE TABLE IF NOT EXISTS  trades (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                symbol TEXT,
                side TEXT,
                qty REAL,
                price REAL,
                pnl REAL,
                timestamp REAL
            );
CREATE TABLE IF NOT EXISTS  sqlite_sequence(name,seq);
CREATE TABLE IF NOT EXISTS  kv (
                key TEXT PRIMARY KEY,
                value TEXT,
                updated_at REAL
            );
CREATE TABLE IF NOT EXISTS  grid_state (
                symbol TEXT PRIMARY KEY,
                status TEXT NOT NULL,
                config_json TEXT NOT NULL,
                levels_json TEXT NOT NULL,
                stats_json TEXT NOT NULL,
                created_at REAL NOT NULL,
                updated_at REAL NOT NULL
            );
CREATE TABLE IF NOT EXISTS  dca_state (
                symbol TEXT PRIMARY KEY,
                rounds_done INTEGER DEFAULT 0,
                total_invested REAL DEFAULT 0,
                avg_price REAL DEFAULT 0,
                next_buy_at REAL,
                status TEXT DEFAULT 'active',
                updated_at REAL NOT NULL
            );
CREATE TABLE IF NOT EXISTS  strategy_state (
                key TEXT PRIMARY KEY,
                value TEXT NOT NULL,
                updated_at REAL NOT NULL
            );
CREATE TABLE IF NOT EXISTS  audit_log (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                timestamp REAL,
                action TEXT,
                details TEXT,
                old_value TEXT,
                new_value TEXT,
                source TEXT
            );
CREATE TABLE IF NOT EXISTS  decisions (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                timestamp REAL,
                date TEXT,
                symbol TEXT,
                type TEXT,
                decision TEXT,
                score REAL,
                price REAL,
                qty REAL,
                side TEXT,
                strategy TEXT,
                reasons TEXT,
                signals TEXT,
                bear_score REAL,
                bear_veto INTEGER,
                bear_reasons TEXT,
                bear_confidence TEXT,
                research TEXT,
                exit_price REAL,
                pnl_pct REAL
            );
CREATE TABLE IF NOT EXISTS  trade_outcomes (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                symbol TEXT NOT NULL,
                entry_time REAL NOT NULL,
                entry_date TEXT,
                entry_price REAL NOT NULL,
                qty REAL NOT NULL,
                score REAL,
                strategy TEXT,
                factors_json TEXT,       -- JSON: {technical, trend, volume, ...}
                context_json TEXT,       -- JSON: {regime, fng, btc_trend, kelly, ...}
                status TEXT DEFAULT 'open',  -- 'open' or 'closed'
                -- Exit data (filled when position closes)
                exit_time REAL,
                exit_price REAL,
                exit_reason TEXT,        -- tp1/tp2/tp3/sl/trailing/max_hold/manual
                -- Computed metrics
                pnl_pct REAL,
                pnl_absolute REAL,
                net_pnl_pct REAL,        -- after fees
                net_pnl_absolute REAL,
                time_held_hours REAL,
                max_profit_pct REAL,
                max_drawdown_pct REAL,
                peak_price REAL,         -- highest price seen during trade
                trough_price REAL,       -- lowest price seen during trade
                is_win INTEGER,          -- 1 if net_pnl > 0
                created_at REAL,
                updated_at REAL
            );
CREATE TABLE IF NOT EXISTS  paper_trades (
                id TEXT PRIMARY KEY,
                symbol TEXT NOT NULL,
                side TEXT NOT NULL,
                order_type TEXT NOT NULL,
                quantity REAL NOT NULL,
                fill_price REAL NOT NULL,
                slippage_pct REAL,
                fee_usdt REAL,
                notional_usdt REAL,
                status TEXT DEFAULT 'filled',
                timestamp REAL NOT NULL,
                details TEXT
            );
CREATE TABLE IF NOT EXISTS  paper_portfolio (
                key TEXT PRIMARY KEY,
                value TEXT NOT NULL,
                updated_at REAL NOT NULL
            );
CREATE TABLE IF NOT EXISTS  paper_pending_orders (
                id TEXT PRIMARY KEY,
                symbol TEXT NOT NULL,
                side TEXT NOT NULL,
                order_type TEXT NOT NULL,
                quantity REAL NOT NULL,
                price REAL NOT NULL,
                stop_price REAL,
                status TEXT DEFAULT 'open',
                created_at REAL NOT NULL,
                expires_at REAL,
                details TEXT
            );
CREATE INDEX idx_trades_symbol ON trades(symbol);
CREATE INDEX idx_trades_time ON trades(timestamp);
CREATE INDEX idx_drawdown_id ON drawdown(id);
CREATE INDEX idx_grid_symbol ON grid_state(symbol);
CREATE INDEX idx_dca_symbol ON dca_state(symbol);
CREATE INDEX idx_strategy_key ON strategy_state(key);
CREATE INDEX idx_audit_time ON audit_log(timestamp);
CREATE INDEX idx_decisions_symbol ON decisions(symbol);
CREATE INDEX idx_decisions_time ON decisions(timestamp);
CREATE INDEX idx_decisions_date ON decisions(date);
CREATE INDEX idx_decisions_type ON decisions(type);
CREATE INDEX idx_outcomes_symbol ON trade_outcomes(symbol);
CREATE INDEX idx_outcomes_status ON trade_outcomes(status);
CREATE INDEX idx_outcomes_entry_time ON trade_outcomes(entry_time);
CREATE INDEX idx_paper_trades_symbol ON paper_trades(symbol);
CREATE INDEX idx_paper_trades_time ON paper_trades(timestamp);
CREATE INDEX idx_paper_pending_symbol ON paper_pending_orders(symbol);
CREATE INDEX idx_outcomes_exit_time ON trade_outcomes(exit_time);
CREATE INDEX idx_outcomes_strategy ON trade_outcomes(strategy);
CREATE INDEX idx_portfolio_strategy ON portfolio(strategy);
CREATE INDEX idx_audit_action ON audit_log(action);
PRAGMA writable_schema = off;
COMMIT;
